-- 114 VERIFY - GENERATED by worker/migrations/drafts/tools/build-114.mjs from 114_plan_split_at_loading.sql. Read only (SELECT). One row.
-- EXPECTED after 114: applied = '114 in place', worker_execute true; split_at_start = loads split at their loading
-- point (0 right after the run, grows with use); parts_waiting = their parts still without a truck (each its own
-- "PROS ANATHESI" line); parts_stock = 0 (such a part is never stock). Before 114: applied = 'before 114'.
SELECT CASE WHEN md5(pg_get_viewdef('public.v_piece_state'::regclass, true)) = 'ac9c5c6dae30a2d56dfc07dee6ac0af3'
                AND (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_split_piece(jsonb,text,text)'::regprocedure) = 'a43e5db008e7d54f7c1bf59f96c5590f'
                AND (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_shipment_problem(bigint)'::regprocedure) = '9f2a79bd4fd6bb5fabbea083c36ede04'
                AND (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_board(date,text)'::regprocedure) = '810f110372c1908b061bcd527257d04c' THEN '114 in place'
            WHEN md5(pg_get_viewdef('public.v_piece_state'::regclass, true)) = '598fd9472beaef97adaf49b1ff431504' THEN 'before 114'
            ELSE '114 PARTLY APPLIED OR CHANGED - stop, send this row to the coordinator' END AS applied,
       has_function_privilege('service_role', 'public.plan_split_piece(jsonb,text,text)', 'EXECUTE') AS worker_execute,
       (SELECT count(*) FROM public.v_piece_pos pp JOIN public.shipments s ON s.id = pp.shipment_id AND s.deleted_at IS NULL
     WHERE pp.is_split AND pp.eff_last_leg_id IS NULL
       AND pp.position_location_id IS DISTINCT FROM (SELECT h.id FROM public.locations h WHERE h.is_hub)) AS split_at_start,
       (SELECT count(*) FROM public.v_piece_state ps JOIN public.v_piece_pos pp ON pp.piece_id = ps.piece_id
         WHERE ps.parent_piece_id IS NOT NULL AND pp.eff_last_leg_id IS NULL AND NOT ps.at_hub) AS parts_waiting,
       (SELECT count(*) FROM public.v_piece_state ps JOIN public.v_piece_pos pp ON pp.piece_id = ps.piece_id
         WHERE ps.is_stock AND pp.eff_last_leg_id IS NULL AND NOT ps.at_hub) AS parts_stock;
